    requires
        old(perm).ptr() == ptr,
        old(perm).is_init(),
    ensures
        final(perm).ptr() == ptr,
        final(perm).is_init(),
        old(perm).value() == *v,
        final(perm).value() == *final(v),
    opens_invariants none
    no_unwind
{
